package oms.screens

/**
 * Simplified administrative boundaries for Ukraine's 24 oblasts and Crimea.
 * Coordinates are derived from an open GeoJSON boundary dataset and reduced
 * for a responsive dashboard Canvas; they are not used for GIS operations.
 */
internal data class UkraineMapPoint(val x: Float, val y: Float)
internal data class UkraineMapRegion(val name: String, private val encodedRings: String) {
    val rings: List<List<UkraineMapPoint>> by lazy {
        encodedRings.split('|').map { ring ->
            ring.split(' ').mapNotNull { point ->
                point.split(',').takeIf { it.size == 2 }?.let { (x, y) ->
                    UkraineMapPoint(x.toFloatOrNull() ?: return@let null, y.toFloatOrNull() ?: return@let null)
                }
            }
        }
    }
}

internal const val ukraineMapWidth = 1_000f
internal const val ukraineMapHeight = 520f

internal fun UkraineMapRegion.contains(point: UkraineMapPoint): Boolean =
    rings.any { ring -> pointInPolygon(point, ring) }

private fun pointInPolygon(point: UkraineMapPoint, polygon: List<UkraineMapPoint>): Boolean {
    if (polygon.size < 3) return false
    var inside = false
    var previous = polygon.last()
    polygon.forEach { current ->
        if ((current.y > point.y) != (previous.y > point.y) &&
            point.x < (previous.x - current.x) * (point.y - current.y) / (previous.y - current.y) + current.x
        ) inside = !inside
        previous = current
    }
    return inside
}

